8. import graphql.schema.idl.ScalarInfo
9. import org.slf4j.LoggerFactory
10. import java.lang.reflect.Method
11. 
12. /**
13.  * @author Andrew Potter
14.  */
15. internal class SchemaClassScanner(
16.     initialDictionary: BiMap<String, Class<*>>,
17.     allDefinitions: List<Definition<*>>,
18.     resolvers: List<GraphQLResolver<*>>,
19.     private val scalars: CustomScalarMap,
20.     private val options: SchemaParserOptions
21. ) {
22.     private val log = LoggerFactory.getLogger(javaClass)
23. 
24.     private val rootInfo = RootTypeInfo.fromSchemaDefinitions(allDefinitions.filterIsInstance<SchemaDefinition>())
25. 
26.     private val queryResolvers = resolvers.filterIsInstance<GraphQLQueryResolver>()
27.     private val mutationResolvers = resolvers.filterIsInstance<GraphQLMutationResolver>()
28.     private val subscriptionResolvers = resolvers.filterIsInstance<GraphQLSubscriptionResolver>()
29. 
30.     private val resolverInfos = resolvers.asSequence().minus(queryResolvers).minus(mutationResolvers).minus(subscriptionResolvers).map { NormalResolverInfo(it, options) }.toList()
31.     private val resolverInfosByDataClass = this.resolverInfos.associateBy { it.dataClassType }
32. 
33.     private val initialDictionary = initialDictionary.mapValues { InitialDictionaryEntry(it.value) }
34.     private val extensionDefinitions = allDefinitions.filterIsInstance<ObjectTypeExtensionDefinition>()
35.     private val inputExtensionDefinitions = allDefinitions.filterIsInstance<InputObjectTypeExtensionDefinition>()
36. 
37.     private val definitionsByName = (allDefinitions.filterIsInstance<TypeDefinition<*>>() - extensionDefinitions - inputExtensionDefinitions).associateBy { it.name }
38.     private val objectDefinitions = (allDefinitions.filterIsInstance<ObjectTypeDefinition>() - extensionDefinitions)
39.     private val objectDefinitionsByName = objectDefinitions.associateBy { it.name }
40.     private val interfaceDefinitionsByName = allDefinitions.filterIsInstance<InterfaceTypeDefinition>().associateBy { it.name }
41. 
42.     private val fieldResolverScanner = FieldResolverScanner(options)
43.     private val typeClassMatcher = TypeClassMatcher(definitionsByName)
44.     private val dictionary = mutableMapOf<TypeDefinition<*>, DictionaryEntry>()
45.     private val unvalidatedTypes = mutableSetOf<TypeDefinition<*>>()
46.     private val queue = linkedSetOf<QueueItem>()
47. 
48.     private val fieldResolversByType = mutableMapOf<ObjectTypeDefinition, MutableMap<FieldDefinition, FieldResolver>>()
49. 
50.     init {
51.         initialDictionary.forEach { (name, clazz) ->
52.             if (!definitionsByName.containsKey(name)) {
53.                 throw SchemaClassScannerError("Class in supplied dictionary '${clazz.name}' specified type name '$name', but a type definition with that name was not found!")
54.             }
55.         }
56. 
57.         if (options.allowUnimplementedResolvers) {
58.             log.warn("Option 'allowUnimplementedResolvers' should only be set to true during development, as it can cause schema errors to be moved to query time instead of schema creation time.  Make sure this is turned off in production.")
59.         }
60.     }
61. 
62.     /**
63.      * Attempts to discover GraphQL Type -> Java Class relationships by matching return types/argument types on known fields
64.      */
65.     fun scanForClasses(): ScannedSchemaObjects {
66. 
67.         // Figure out what query, mutation and subscription types are called
68.         val rootTypeHolder = RootTypesHolder(options, rootInfo, definitionsByName, queryResolvers, mutationResolvers, subscriptionResolvers)
69. 
70.         handleRootType(rootTypeHolder.query)
71.         handleRootType(rootTypeHolder.mutation)
72.         handleRootType(rootTypeHolder.subscription)
73. 
74.         scanQueue()
75. 
76.         // Loop over all objects scanning each one only once for more objects to discover.
77.         do {
78.             do {
79.                 // Require all implementors of discovered interfaces to be discovered or provided.
80.                 handleDictionaryTypes(getAllObjectTypesImplementingDiscoveredInterfaces()) { "Object type '${it.name}' implements a known interface, but no class could be found for that type name.  Please pass a class for type '${it.name}' in the parser's dictionary." }
81.             } while (scanQueue())
82. 
83.             // Require all members of discovered unions to be discovered.
84.             handleDictionaryTypes(getAllObjectTypeMembersOfDiscoveredUnions()) { "Object type '${it.name}' is a member of a known union, but no class could be found for that type name.  Please pass a class for type '${it.name}' in the parser's dictionary." }
85.         } while (scanQueue())
86. 
87.         // Find unused types and include them if required
88.         if (options.includeUnusedTypes) {
89.             do {
90.                 val unusedDefinitions = (definitionsByName.values - (dictionary.keys.toSet() + unvalidatedTypes))
91.                     .filter { definition -> definition.name != "PageInfo" }
92.                     .filterIsInstance<ObjectTypeDefinition>().distinct()
93. 
94.                 if (unusedDefinitions.isEmpty()) {
95.                     break
96.                 }
97. 
98.                 val unusedDefinition = unusedDefinitions.first()
99. 
100.                 handleDictionaryTypes(listOf(unusedDefinition)) { "Object type '${it.name}' is unused and includeUnusedTypes is true. Please pass a class for type '${it.name}' in the parser's dictionary." }
101.             } while (scanQueue())
102.         }
103. 
104.         return validateAndCreateResult(rootTypeHolder)
105.     }
106. 
107.     private fun scanQueue(): Boolean {
108.         if (queue.isEmpty()) {
109.             return false
110.         }
111. 
112.         while (queue.isNotEmpty()) {
113.             scanQueueItemForPotentialMatches(queue.iterator().run { val item = next(); remove(); item })
114.         }
115. 
116.         return true
117.     }
118. 
119.     /**
120.      * Adds all root resolvers for a type to the list of classes to scan
121.      */
122.     private fun handleRootType(rootType: RootType?) {
123.         if (rootType == null) {
124.             return
125.         }
126. 
127.         unvalidatedTypes.add(rootType.type)
128.         scanInterfacesOfType(rootType.type)
129.         scanResolverInfoForPotentialMatches(rootType.type, rootType.resolverInfo)
130.     }
131. 
132.     private fun validateAndCreateResult(rootTypeHolder: RootTypesHolder): ScannedSchemaObjects {
133.         initialDictionary
134.             .filter { !it.value.accessed }
135.             .forEach {
136.                 log.warn("Dictionary mapping was provided but never used, and can be safely deleted: \"${it.key}\" -> ${it.value.get().name}")
137.             }
138. 
139.         val observedDefinitions = dictionary.keys.toSet() + unvalidatedTypes
140. 
141.         // The dictionary doesn't need to know what classes are used with scalars.
142.         // In addition, scalars can have duplicate classes so that breaks the bi-map.
143.         // Input types can also be excluded from the dictionary, since it's only used for interfaces, unions, and enums.
144.         // Union types can also be excluded, as their possible types are resolved recursively later
145.         val dictionary = try {
146.             BiMap.unmodifiableBiMap(BiMap.create<TypeDefinition<*>, JavaType>().also {
147.                 dictionary
148.                     .filter {
149.                         it.value.javaType != null
150.                             && it.value.typeClass() != java.lang.Object::class.java
151.                             && !java.util.Map::class.java.isAssignableFrom(it.value.typeClass())
152.                             && it.key !is InputObjectTypeDefinition
153.                             && it.key !is UnionTypeDefinition
154.                     }.mapValuesTo(it) { it.value.javaType }
155.             })
156.         } catch (t: Throwable) {
157.             throw SchemaClassScannerError("Error creating bimap of type => class", t)
158.         }
159.         val scalarDefinitions = observedDefinitions.filterIsInstance<ScalarTypeDefinition>()
160. 
161.         // Ensure all scalar definitions have implementations and add the definition to those.
162.         val scalars = scalarDefinitions
163.             .filter {
164.                 // Filter for any defined scalars OR scalars that aren't defined but also aren't standard
165.                 scalars.containsKey(it.name) || !ScalarInfo.GRAPHQL_SPECIFICATION_SCALARS_DEFINITIONS.containsKey(it.name)
166.             }.map { definition ->
167.                 val provided = scalars[definition.name]
168.                     ?: throw SchemaClassScannerError("Expected a user-defined GraphQL scalar type with name '${definition.name}' but found none!")
169.                 GraphQLScalarType.newScalar()
170.                     .name(provided.name)
171.                     .description(getDocumentation(definition, options) ?: provided.description)
172.                     .coercing(provided.coercing)
173.                     .definition(definition)
174.                     .build()
175.             }.associateBy { it.name!! }
176. 
177.         val unusedDefinitions = (definitionsByName.values - observedDefinitions).toSet()
178.         unusedDefinitions
179.             .filter { definition -> definition.name != "PageInfo" }
180.             .forEach { definition ->
181.                 log.warn("Schema type was defined but can never be accessed, and can be safely deleted: ${definition.name}")
182.             }
183. 
184.         val fieldResolvers = fieldResolversByType.flatMap { it.value.map { it.value } }
185.         val observedNormalResolverInfos = fieldResolvers.map { it.resolverInfo }.distinct().filterIsInstance<NormalResolverInfo>()
186.         val observedMultiResolverInfos = fieldResolvers.map { it.resolverInfo }.distinct().filterIsInstance<MultiResolverInfo>().flatMap { it.resolverInfoList }
187. 
188.         (resolverInfos - observedNormalResolverInfos - observedMultiResolverInfos).forEach { resolverInfo ->
189.             log.warn("Resolver was provided but no methods on it were used in data fetchers, and can be safely deleted: ${resolverInfo.resolver}")
190.         }
191. 
192.         validateRootResolversWereUsed(rootTypeHolder.query, fieldResolvers)
193.         validateRootResolversWereUsed(rootTypeHolder.mutation, fieldResolvers)
194.         validateRootResolversWereUsed(rootTypeHolder.subscription, fieldResolvers)
195. 
196.         return ScannedSchemaObjects(dictionary, observedDefinitions + extensionDefinitions + inputExtensionDefinitions, scalars, rootInfo, fieldResolversByType.toMap(), unusedDefinitions)
197.     }
