199.     private fun validateRootResolversWereUsed(rootType: RootType?, fieldResolvers: List<FieldResolver>) {
200.         if (rootType == null) {
201.             return
202.         }
203. 
204.         val observedRootTypes = fieldResolvers.asSequence().filter { it.resolverInfo is RootResolverInfo && it.resolverInfo == rootType.resolverInfo }.map { it.search.type }.toSet()
205.         rootType.resolvers.forEach { resolver ->
206.             if (rootType.resolverInfo.getRealResolverClass(resolver, options) !in observedRootTypes) {
207.                 log.warn("Root ${rootType.name} resolver was provided but no methods on it were used in data fetchers for GraphQL type '${rootType.type.name}'!  Either remove the ${rootType.resolverInterface.name} interface from the resolver or remove the resolver entirely: $resolver")
208.             }
209.         }
210.     }
