212.     private fun getAllObjectTypesImplementingDiscoveredInterfaces(): List<ObjectTypeDefinition> {
213.         return dictionary.keys.filterIsInstance<InterfaceTypeDefinition>().map { iface ->
214.             objectDefinitions.filter { obj -> obj.implements.filterIsInstance<TypeName>().any { it.name == iface.name } }
215.         }.flatten().distinctBy { it.name }
216.     }
