218.     private fun getAllObjectTypeMembersOfDiscoveredUnions(): List<ObjectTypeDefinition> {
219.         val unionTypeNames = dictionary.keys.filterIsInstance<UnionTypeDefinition>().map { union -> union.name }.toSet()
220.         return dictionary.keys.filterIsInstance<UnionTypeDefinition>().map { union ->
221.             union.memberTypes.filterIsInstance<TypeName>().filter { !unionTypeNames.contains(it.name) }.map {
222.                 objectDefinitionsByName[it.name]
223.                     ?: throw SchemaClassScannerError("No object type found with name '${it.name}' for union: $union")
224.             }
225.         }.flatten().distinct()
226.     }
