228.     private fun handleDictionaryTypes(types: List<ObjectTypeDefinition>, failureMessage: (ObjectTypeDefinition) -> String) {
229.         types.forEach { type ->
230.             val dictionaryContainsType = dictionary.filter { it.key.name == type.name }.isNotEmpty()
231.             if (!unvalidatedTypes.contains(type) && !dictionaryContainsType) {
232.                 val initialEntry = initialDictionary[type.name]
233.                     ?: throw SchemaClassScannerError(failureMessage(type))
234.                 handleFoundType(type, initialEntry.get(), DictionaryReference())
235.             }
236.         }
237.     }
