492.         private val mutationResolverInfo = RootResolverInfo(mutationResolvers, options)
493.         private val subscriptionResolverInfo = RootResolverInfo(subscriptionResolvers, options)
494. 
495.         val query = createRootType("query", queryDefinition, queryName, true, queryResolvers, GraphQLQueryResolver::class.java, queryResolverInfo)
496.         val mutation = createRootType("mutation", mutationDefinition, mutationName, rootInfo.isMutationRequired(), mutationResolvers, GraphQLMutationResolver::class.java, mutationResolverInfo)
