500.             if (type == null) {
501.                 if (required) {
502.                     throw SchemaClassScannerError("Type definition for root $name type '$typeName' not found!")
503.                 }
504. 
505.                 return null
506.             }
507. 
508.             if (type !is ObjectTypeDefinition) {
509.                 throw SchemaClassScannerError("Expected root query type's type to be ${ObjectTypeDefinition::class.java.simpleName}, but it was ${type.javaClass.simpleName}")
510.             }
511. 
512.             // Find query resolver class
513.             if (resolvers.isEmpty()) {
514.                 throw SchemaClassScannerError("No Root resolvers for $name type '$typeName' found!  Provide one or more ${resolverInterface.name} to the builder.")
515.             }
