                .apply {
                    directive.arguments.forEach { arg ->
                        argument(GraphQLArgument.newArgument()
                            .name(arg.name)
                            .type(buildDirectiveInputType(arg.value))
                            .valueLiteral(arg.value)
                            .build())
                    }
                }
                .build()

            output.add(graphQLDirective)
        }
    }

    return output.toTypedArray()
}

